(function(root){
'use strict';
const noteIcon='<svg viewBox="0 0 20 20" width="16" height="16" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.3"><rect x="4" y="2.8" width="12" height="14.4" rx="2"/><path d="M7 7h6M7 10h6M7 13h3"/></svg>';
function taskRow(t,c,kind='task-card'){
  const p=c.state.projects.find(p=>p.id===t.projectId),hasNotes=Boolean(t.notes?.trim());
  const executor=t.executor==='ai'?`<span class="assignment-tag ai">IA${t.assignee?' · '+c.esc(t.assignee):''} · Sin ejecutar</span>`:t.executor==='human'?`<span class="assignment-tag">Humano${t.assignee?' · '+c.esc(t.assignee):' · Por definir'}</span>`:'';
  return `<article class="${kind} task-line mention-wrap ${t.done?'done':''}" data-task-id="${c.esc(t.id)}" style="${c.companyStyle(t.company)}"><label class="task-toggle"><input type="checkbox" class="check" data-task-check="${c.esc(t.id)}" aria-label="${t.done?'Volver a pendiente':'Completar'} ${c.esc(t.title)}" ${t.done?'checked':''}></label><div class="line-body"><textarea class="line-title" rows="1" data-inline-task="${c.esc(t.id)}" aria-label="Editar tarea: ${c.esc(t.title)}" maxlength="200" spellcheck="false">${c.esc(t.title)}</textarea><div class="line-meta">${t.time?`<time>${c.esc(c.model.formatTime12(t.time))}</time>`:''}${c.tag(t.company)}${p?`<span>${c.esc(p.title)}</span>`:''}${executor}${t.seriesId?'<span class="repeat-tag" title="Cada fecha se completa por separado">↻</span>':''}${t.decision?'<span class="decision-tag">Decisión</span>':''}${t.priority?'<span class="priority-tag">Prioridad</span>':''}</div></div><button type="button" class="line-details ${hasNotes?'has-notes':''}" data-open-task="${c.esc(t.id)}" aria-label="Notas y detalles: ${c.esc(t.title)}" title="Notas y detalles${hasNotes?' · Tiene notas':''}">${noteIcon}${hasNotes?'<i aria-hidden="true"></i>':''}</button><span class="line-error" role="alert"></span></article>`;
}
function completedList(tasks,c){
  return tasks.length?'<section class="completed-tasks" aria-label="Tareas hechas del día"><h3>Hechas <span>'+tasks.length+'</span></h3>'+tasks.map(t=>taskRow(t,c)).join('')+'</section>':'';
}
function quickLine(d,c,time='',quadrant=2){
  const key=[d,time,quadrant].join('|');
  return `<form class="inline-task notebook-add mention-wrap" data-quick-date="${c.esc(d)}" data-quick-time="${c.esc(time)}" data-quick-quadrant="${quadrant}"><input aria-label="Nueva tarea ${c.esc(d)}${time?' '+c.model.formatTime12(time):''}${c.view==='matrix'?' cuadrante '+quadrant:''}" placeholder="Escribe aquí…" value="${c.esc(c.drafts.get(key)||'')}" maxlength="200" autocomplete="off" spellcheck="false"><button type="submit" class="line-submit" aria-label="Guardar renglón ${c.esc(d)}${time?' '+c.model.formatTime12(time):''}" title="Enter para guardar">↵</button><span class="line-error" role="alert"></span></form>`;
}
function day(c){
  const all=c.onDate(c.date),tasks=all.filter(t=>!t.done),completed=all.filter(t=>t.done),priorities=tasks.filter(t=>t.priority),withoutTime=tasks.filter(t=>!t.time),goalIds=[...new Set(tasks.map(t=>t.goalId).filter(Boolean))];
  const slots=Array.from({length:1440/c.step},(_,i)=>{const minute=i*c.step,time=c.model.timeLabel(minute),rows=c.model.slotTasks(tasks,minute,c.step);return `<div class="notebook-hour" data-slot-time="${time}"><time class="notebook-time">${c.model.formatTime12(time)}</time><div class="notebook-slot" data-drop-date="${c.date}" data-drop-time="${time}">${rows.map(t=>taskRow(t,c,'timed-task')).join('')}${quickLine(c.date,c,time)}</div></div>`;}).join('');
  return `<section class="day-intent"><label for="day-intent">Resultado que quiero hoy</label><input id="day-intent" data-note-key="outcome-${c.date}" placeholder="Escribe el resultado que quieres dejar listo…" value="${c.esc(c.state.dayNotes['outcome-'+c.date]||'')}" maxlength="300"></section><div class="notebook-day-layout"><section class="notebook-paper" aria-label="Libreta del día"><div class="notebook-paper-head"><span>Horario · Bogotá · AM/PM</span><small>Enter: otro renglón · @: negocio o proyecto</small></div><div class="notebook-day-scroll" id="day-agenda">${slots}</div>${completedList(completed,c)}</section><aside class="notebook-day-side"><section class="loose-tasks"><h2>Sin hora</h2>${withoutTime.map(t=>taskRow(t,c)).join('')}${quickLine(c.date,c)}</section><section class="paper-notes"><h2>Notas del día</h2><textarea class="simple-note" aria-label="Notas del día" data-note-key="${c.date}" placeholder="Escribe una nota…" maxlength="8000">${c.esc(c.state.dayNotes[c.date]||'')}</textarea></section><details class="notebook-context"><summary>Prioridades y metas</summary>${priorities.map(t=>taskRow(t,c)).join('')}${goalIds.map(id=>c.state.goals.find(g=>g.id===id)).filter(Boolean).map(c.goalMini).join('')}${!priorities.length&&!goalIds.length?'<p class="empty">Puedes vincularlas desde la tarjeta. No es obligatorio para escribir.</p>':''}</details><details class="notebook-context"><summary>Rutinas</summary>${['morning','anytime','night'].map(group=>{const habits=c.state.habits.filter(h=>h.group===group&&c.model.habitDue(h,c.date));return habits.length?`<h3>${group==='morning'?'Mañana':group==='night'?'Noche':'Durante el día'}</h3>${habits.map(h=>c.habitItem(h,c.date)).join('')}`:'';}).join('')}</details></aside></div>`;
}
function week(c){
  const start=c.model.monday(c.date);
  if(c.mode==='hours')return weekHours(start,c);
  return `<div class="board-wrap" id="week-wrap"><div class="week-board notebook-week">${Array.from({length:7},(_,i)=>{const d=c.model.addDays(start,i);return `<section class="day-column ${d===c.today?'is-today':''}" data-drop-date="${d}"><button class="day-heading" data-open-day="${d}"><span>${c.dayName(d)}<small>${c.shortDate(d).split(' ')[1]||''}</small></span><span class="date-circle">${Number(d.slice(-2))}</span></button><div class="week-lines">${c.onDate(d).filter(t=>!t.done).map(t=>taskRow(t,c)).join('')}${quickLine(d,c)}</div>${c.inlineRoutine(d)}${completedList(c.onDate(d).filter(t=>t.done),c)}</section>`;}).join('')}</div></div>${summary(c)}`;
}
function weekHours(start,c){
  return `<div class="board-wrap"><div class="hour-week notebook-week-hours"><div class="hour-week-header"><span></span>${Array.from({length:7},(_,i)=>{const d=c.model.addDays(start,i);return `<button data-open-day="${d}" class="${d===c.today?'today':''}">${c.dayName(d).slice(0,3)} · ${Number(d.slice(-2))}</button>`;}).join('')}</div><div class="hour-week-body" id="week-hours">${Array.from({length:1440/c.step},(_,i)=>{const minute=i*c.step,time=c.model.timeLabel(minute);return `<div class="week-hour-row" data-slot-time="${time}"><time>${c.model.formatTime12(time)}</time>${Array.from({length:7},(_,j)=>{const d=c.model.addDays(start,j);return `<div class="week-hour-cell" data-drop-date="${d}" data-drop-time="${time}">${c.model.slotTasks(c.onDate(d).filter(t=>!t.done),minute,c.step).map(t=>taskRow(t,c,'timed-task')).join('')}${quickLine(d,c,time)}</div>`;}).join('')}</div>`;}).join('')}</div><div class="week-completed-row"><span></span>${Array.from({length:7},(_,i)=>{const d=c.model.addDays(start,i);return '<div>'+completedList(c.onDate(d).filter(t=>t.done),c)+'</div>';}).join('')}</div></div></div>${summary(c)}`;
}
function summary(c){
  const start=c.model.monday(c.date),end=c.model.addDays(start,6),goals=c.state.goals.filter(g=>g.level==='week'&&g.end>=start&&g.start<=end&&(c.company==='all'||g.company===c.company));
  return `<div class="notebook-week-bottom"><section class="paper-notes"><h2>Notas de la semana</h2><textarea class="simple-note" aria-label="Notas de la semana" data-note-key="week-${start}" placeholder="Escribe una nota…" maxlength="8000">${c.esc(c.state.dayNotes['week-'+start]||'')}</textarea></section><details class="notebook-context"><summary>Metas y decisiones de la semana</summary>${goals.map(c.goalMini).join('')}${c.filteredTasks().filter(t=>t.decision&&!t.done&&t.date>=start&&t.date<=end).map(t=>taskRow(t,c)).join('')}<button class="text-button" data-page="goals">Ver metas →</button></details></div>`;
}
function matrix(c){
  const cells=[[1,'Haz','Urgente · Importante'],[2,'Agenda','No urgente · Importante'],[3,'Delega','Urgente · No importante'],[4,'Descarta','No urgente · No importante']];
  const tasks=c.filteredTasks().filter(t=>c.executorFilter==='all'||(t.executor||'self')===c.executorFilter);
  return `<div class="matrix-axes"><span>Urgente</span><span>No urgente</span></div><div class="notebook-matrix">${cells.map(([id,title,description])=>`<section class="matrix-cell matrix-${id}"><header><h2>${title}</h2><span>${description}</span></header>${tasks.filter(t=>(t.quadrant||2)===id).map(t=>taskRow(t,c)).join('')}${quickLine(c.date,c,'',id)}</section>`).join('')}</div><p class="matrix-note">@ identifica negocio o proyecto · #humano, #ia o #yo asigna responsable. Asignar no envía mensajes ni ejecuta agentes. «Descarta» clasifica; no borra el historial.</p>`;
}
root.NotebookView={taskRow,quickLine,day,week,weekHours,summary,matrix};
})(window);
